import React, { createContext, useContext, useState, useEffect } from 'react';
import { getData, saveData } from '../services/localStorageService';
import { packages as samplePackages } from '../data/sampleData';
import { generateId } from '../utils/helpers';

const PackageContext = createContext();

export const PackageProvider = ({ children }) => {
  const [packages, setPackages] = useState([]);

  useEffect(() => {
    const stored = getData('packages');
    if (stored.length === 0) {
      saveData('packages', samplePackages);
      setPackages(samplePackages);
    } else {
      setPackages(stored);
    }
  }, []);

  const addPackage = (pkg) => {
    const newPkg = { ...pkg, id: generateId() };
    const updated = [...packages, newPkg];
    saveData('packages', updated);
    setPackages(updated);
    return newPkg;
  };

  const updatePackage = (id, updates) => {
    const updated = packages.map(p => p.id === id ? { ...p, ...updates } : p);
    saveData('packages', updated);
    setPackages(updated);
  };

  const deletePackage = (id) => {
    const updated = packages.filter(p => p.id !== id);
    saveData('packages', updated);
    setPackages(updated);
  };

  const getPackageById = (id) => packages.find(p => p.id === id);

  return (
    <PackageContext.Provider value={{ packages, addPackage, updatePackage, deletePackage, getPackageById }}>
      {children}
    </PackageContext.Provider>
  );
};

export const usePackages = () => useContext(PackageContext);
export default PackageContext;
